# Tagliamo o gestiamo in automatico la dimensione quadrata
side = int(np.sqrt(len(raw_data)))
if len(raw_data) != side * side:
    print(f"Nota: Trovati {len(raw_data)} elementi. Tronco a {side * side} per formare una griglia {side}x{side}.")
    raw_data = raw_data[:side * side]

Z = np.array(raw_data).reshape(side, side)

x = np.linspace(-1.0, 1.0, side)
y = np.linspace(-1.0, 1.0, side)
X, Y = np.meshgrid(x, y)

fig = plt.figure(figsize=(10, 7))
ax = fig.add_subplot(projection='3d')

surf = ax.plot_surface(X, Y, Z, cmap='plasma', edgecolor='none', alpha=0.9)

ax.set_title("Visualizzazione 3D della Funzione", fontsize=14, color='white')
ax.set_xlabel("Asse X")
ax.set_ylabel("Asse Y")
ax.set_zlabel("Asse Z")

fig.patch.set_facecolor('#1e1e1e')
ax.set_facecolor('#1e1e1e')
ax.xaxis.label.set_color('white')
ax.yaxis.label.set_color('white')
ax.zaxis.label.set_color('white')
ax.tick_params(colors='white')

fig.colorbar(surf, shrink=0.5, aspect=5)
plt.show()